mapper.select:
SELECT mn.id, mn.title, mn.content, mn.publish_date, mn.is_published, mn.create_time, mn.update_time, mn.create_user, mn.update_user, ca.name AS createUserName, ua.name AS updateUserName FROM moving_news mn LEFT JOIN admin ca ON mn.create_user = ca.id LEFT JOIN admin ua ON mn.update_user = ua.id
AND mn.title LIKE CONCAT('%', #{title}, '%')
AND mn.content LIKE CONCAT('%', #{content}, '%')
AND mn.is_published = #{isPublished}
AND mn.publish_date >= #{publishDateStart}
AND mn.publish_date <= #{publishDateEnd}
ORDER BY mn.id
